function GuideStepDesWithCharacter:GetPositionDataWithScreenPosition(rectTrans, size)
    local posXOffset = 62.5
    local widthRoleNode = 170
    local canvasRootWidth = CS.Engine.UI.UIModule.RootCanvas.transform.sizeDelta.x
    local valueLimit = canvasRootWidth / 2
    local width = size.x
    local height = size.y
    local offsetXWithPivot = rectTrans.anchoredPosition.x
    local offsetYWithPivot = rectTrans.anchoredPosition.y
    local controllerHeight = self.goRect.sizeDelta.y
    local aiNodeWidth = self.Father_TxtWithLayout.sizeDelta.x
    local posX
    if offsetXWithPivot <= 0 then
        posX = offsetXWithPivot + width/2 + aiNodeWidth/2
        if (posX - aiNodeWidth / 2 - widthRoleNode) < -valueLimit  then
            --posX = posX + (-valueLimit - (posX - aiNodeWidth / 2 - widthRoleNode))
            posX = aiNodeWidth / 2 +widthRoleNode - valueLimit + posXOffset
        end
    else
        posX = offsetXWithPivot - width/2 - aiNodeWidth/2
        if posX + aiNodeWidth / 2 > valueLimit then
            posX = aiNodeWidth / 2 - valueLimit
        end
    end
    --local posX = offsetXWithPivot > 0 and offsetXWithPivot - width/2 - aiNodeWidth/2 or offsetXWithPivot + width/2 + aiNodeWidth/2
    local posY = offsetYWithPivot > 0 and offsetYWithPivot - height/2 - controllerHeight/2
            or offsetYWithPivot + height/2 + controllerHeight/2
    return Vector2.New(posX, posY)
end

function GuideStepDesWithCharacter:SetPositionDataWithScreenPosition(rectTrans, size)
    self.goRect.pivot = Vector2.New(0.5, 0.5)
    self.goRect.anchorMin = Vector2.New(0.5, 0.5)
    self.goRect.anchorMax = Vector2.New(0.5, 0.5)
    self.Father_TxtWithLayout.pivot = Vector2.New(0.5, 0.5)
    self.Father_TxtWithLayout.anchoredPosition = Vector2.zero
    self.goRect.anchoredPosition = self:GetPositionDataWithScreenPosition(rectTrans,size)
    self:SetDescTxtPivotY(rectTrans.anchoredPosition)
    self:SetNodeLineWithPosition(rectTrans)
end

function GuideStepDesWithCharacter:SetControllerPositionData(dataPosition)
    local id = checkInt(dataPosition.position)
    local data = GamePlayGuideMgr.CONFIG_POSITION[id]
    if isNull(data) then return end
    local offset = dataPosition.offset
    self.goRect.pivot = data.pivot
    self.goRect.anchorMin = data.anchorMin
    self.goRect.anchorMax = data.anchorMax
    self.goRect.anchoredPosition = data.position
    self.Father_TxtWithLayout.pivot = data.RootAIPivot
    self:SetDescTxtPivotY(data.position)
    self.goRect.anchoredPosition = Vector2.New(self.goRect.anchoredPosition.x + offset.x, self.goRect.anchoredPosition.y + offset.y)
    self:CleanLineShow()
    --self:SetNodeLineWithConfigPosition(id)
end

function GuideStepDesWithCharacter:SetDescTxtPivotY(position)
    if not IsNull(self.Father_TxtWithLayout) then
        local valueY = position.y > 0 and GamePlayGuideMgr.TXT_PIVOT_Y.Down or GamePlayGuideMgr.TXT_PIVOT_Y.TOP
        self.Father_TxtWithLayout.pivot = Vector2.New(self.Father_TxtWithLayout.pivot.x, valueY)
        local posY = position.y > 0 and GamePlayGuideMgr.TXT_POS_Y.Down or GamePlayGuideMgr.TXT_POS_Y.TOP
        self.Father_TxtWithLayout.anchoredPosition = Vector2.New(self.Father_TxtWithLayout.anchoredPosition.x, posY)
    end
end

