function GuideStepDesWithCharacter:GetLineIndex(rectTrans)
    local aX = rectTrans.anchoredPosition.x
    local aY = rectTrans.anchoredPosition.y
    if aX < 0 and aY < 0 then
        return 3
    elseif aX > 0 and aY < 0 then
        return 4
    elseif aX > 0 and aY > 0 then
        return 2
    elseif aX < 0 and aY > 0 then
        return 1
    end
end

