---GetRootAnchorPos
---获得 节点 锚点坐标
---@param pos integer @ 位置 Index
function GuideStepDesWithCharacter:GetRootAnchorPos(pos)
    local aimPos
    if pos == ROOT_POS.Up then
        aimPos = V2_POS_UP
    elseif pos == ROOT_POS.Down then
        aimPos = V2_POS_DOWN
    elseif pos == ROOT_POS.Middle then
        aimPos = Vector2.zero
    end
    return aimPos
end

---SetImgLightColor
---设置 语音高亮 图片颜色
function GuideStepDesWithCharacter:SetImgLightColor(path)

    local aimColor
    if path == PATH_ROLE_1 then
        aimColor = COLOR_BLUE
    elseif path == PATH_ROLE_2 then
        aimColor = COLOR_YELLOW
    elseif path == PATH_ROLE_3 then
        aimColor = COLOR_RED
    elseif path == PATH_ROLE_4 then
        aimColor = COLOR_PINK
    end
    return aimColor
end

