function GuideStepDesWithCharacter:PlayGuiderAnimation()
    xTry(function()
        self.Img_WithRole:Clear()
        local entry = self.Img_WithRole.AnimationState:SetAnimation(0, "play2", true)
        local duration = checkNumber(entry.Animation.Duration) - 0.2
        self.Img_WithRole.AnimationState:AddAnimation(0, "idle", true, duration);
    end)
end

